#!/usr/bin/env bash
# Autonomously generated by an AI agent: evidence capture for the RCA/CUE physical test.
# Requires a human to run the scenarios in packaging/android/qa/RCA_CUE_PROTOCOL.md.
set -euo pipefail

adb_bin=${ADB:-adb}
script_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
output_dir=${1:-"rca-cue-capture-$(date -u +%Y%m%dT%H%M%SZ)"}

if ! command -v "$adb_bin" >/dev/null 2>&1; then
    echo "ADB no encontrado. Configura ADB=/ruta/a/adb." >&2
    exit 1
fi

if ! "$adb_bin" get-state >/dev/null 2>&1; then
    echo "No hay un teléfono ADB accesible. Revisa la autorización de depuración." >&2
    echo "Si hay varios dispositivos, configura ANDROID_SERIAL." >&2
    exit 1
fi

if [[ -e "$output_dir" ]]; then
    echo "La carpeta ya existe: $output_dir. Elige otra para no mezclar pruebas." >&2
    exit 1
fi
mkdir -p "$output_dir"

"$adb_bin" shell dumpsys package org.mixxx >"$output_dir/package.txt" 2>&1 || true
grep -E 'versionCode|versionName' "$output_dir/package.txt" >"$output_dir/version.txt" || true
"$adb_bin" shell getprop ro.product.model >"$output_dir/device.txt" 2>&1 || true
date -u +%Y-%m-%dT%H:%M:%SZ >"$output_dir/captured_at.txt"

ADB="$adb_bin" bash "$script_dir/android_audio_diagnostics.sh" "$output_dir/diagnostics"

echo "Captura guardada en: $output_dir"
echo "Antes de desconectar el teléfono, anota en el protocolo el escenario que fallo."
# End of script autonomously generated by an AI agent.
